static void format_integer(long long value, char *out) {
    char buf[32];
    int len = 0;
    char sign = 0;
    unsigned long long v;
    if (value < 0) {
        sign = '-';
        v = (unsigned long long)(-(value + 1)) + 1ULL;
    } else {
        v = (unsigned long long)value;
    }
    if (v == 0) {
        buf[len++] = '0';
    } else {
        while (v > 0) {
            buf[len++] = (char)('0' + (int)(v % 10));
            v /= 10;
        }
    }
    size_t pos = 0;
    if (sign) out[pos++] = sign;
    for (int i = len - 1; i >= 0; i--) {
        out[pos++] = buf[i];
        if (i > 0 && (i % 3) == 0) {
            out[pos++] = ',';
        }
    }
    out[pos] = '\0';
}

