static void counter_add(Counter **arr, size_t *len, size_t *cap, const char *name) {
    for (size_t i = 0; i < *len; i++) {
        if (strcmp((*arr)[i].name, name) == 0) {
            (*arr)[i].count++;
            return;
        }
    }
    if (*len == *cap) {
        *cap = (*cap) ? (*cap) * 2 : 8;
        Counter *tmp = (Counter *)realloc(*arr, (*cap) * sizeof(Counter));
        if (!tmp) { perror("realloc"); exit(1); }
        *arr = tmp;
    }
    (*arr)[*len].name = my_strdup(name);
    (*arr)[*len].count = 1;
    (*len)++;
}

