function fetchProducts(): Promise<Product[]> {
  return new Promise<Product[]>((resolve, reject) => {
    const req = http.get(
      "http://127.0.0.1:18923/api/products",
      (res) => {
        let data = "";
        res.on("data", (chunk) => {
          data += chunk;
        });
        res.on("end", () => {
          try {
            const parsed = JSON.parse(data) as Product[];
            resolve(parsed);
          } catch (err) {
            reject(err as Error);
          }
        });
      }
    );
    req.on("error", (err: Error) => reject(err));
  });
}

