function multiply(A: number[][], B: number[][], n: number): number[][] {
    const C: number[][] = [];
    for (let i = 0; i < n; i++) {
        C[i] = [];
        for (let j = 0; j < n; j++) {
            let sum = 0;
            for (let k = 0; k < n; k++) {
                sum += A[i][k] * B[k][j];
            }
            C[i][j] = sum;
        }
    }
    return C;
}

function determinant(A: number[][], n: number): number {
    if (n === 1) return A[0][0];
    if (n === 2) return A[0][0] * A[1][1] - A[0][1] * A[1][0];
    let det = 0;
    for (let j = 0; j < n; j++) {
        const minor: number[][] = [];
        for (let i = 1; i < n; i++) {
            const row: number[] = [];
            for (let k = 0; k < n; k++) {
                if (k !== j) row.push(A[i][k]);
            }
            minor.push(row);
        }
        det += (j % 2 === 0 ? 1 : -1) * A[0][j] * determinant(minor, n - 1);
    }
    return det;
}

function formatMatrix(M: number[][], n: number): string {
    const lines: string[] = [];
    for (let i = 0; i < n; i++) {
        const rowStr = M[i].map((v) => String(v).padStart(4)).join(" ");
        lines.push("  " + rowStr);
    }
    return lines.join("\n");
}

