func pad(_ v: Int, width: Int) -> String {
    let s = String(v)
    if s.count >= width { return s }
    return String(repeating: " ", count: width - s.count) + s
}

func multiply(_ a: [[Int]], _ b: [[Int]]) -> [[Int]] {
    let n = a.count
    let m = b[0].count
    let k = b.count
    var result = Array(repeating: Array(repeating: 0, count: m), count: n)
    for i in 0..<n {
        for j in 0..<m {
            var sum = 0
            for l in 0..<k {
                sum += a[i][l] * b[l][j]
            }
            result[i][j] = sum
        }
    }
    return result
}

func determinant(_ m: [[Int]]) -> Int {
    let n = m.count
    if n == 1 { return m[0][0] }
    if n == 2 { return m[0][0]*m[1][1] - m[0][1]*m[1][0] }
    var det = 0
    for j in 0..<n {
        var minor = [[Int]]()
        for r in 1..<n {
            var row = [Int]()
            for c in 0..<n {
                if c != j { row.append(m[r][c]) }
            }
            minor.append(row)
        }
        let sign = (j % 2 == 0) ? 1 : -1
        det += sign * m[0][j] * determinant(minor)
    }
    return det
}

