use std::collections::BTreeMap;
use std::fs;
use std::io::{self, Write};
use std::path::Path;

fn walk(
    base: &Path,
    dir: &Path,
    groups: &mut BTreeMap<String, BTreeMap<String, (usize, usize)>>,
) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let path = entry.path();
        let ft = match entry.file_type() {
            Ok(ft) => ft,
            Err(_) => continue,
        };
        // Do not follow symlinks (file_type() does not traverse symlinks).
        if ft.is_symlink() {
            continue;
        }
        if ft.is_dir() {
            walk(base, &path, groups);
        } else if ft.is_file() {
            process_file(base, &path, groups);
        }
    }
}

fn process_file(
    base: &Path,
    path: &Path,
    groups: &mut BTreeMap<String, BTreeMap<String, (usize, usize)>>,
) {
    let data = match fs::read(path) {
        Ok(d) => d,
        Err(_) => return,
    };
    let chars = data.len(); // total bytes in the file
    let lines = data.iter().filter(|&&b| b == b'\n').count();

    let ext = match path.extension() {
        Some(e) => format!(".{}", e.to_string_lossy()),
        None => String::new(),
    };

    let rel = match path.strip_prefix(base) {
        Ok(r) => r.to_string_lossy().replace('\\', "/"),
        Err(_) => path.to_string_lossy().replace('\\', "/"),
    };

    groups.entry(ext).or_default().insert(rel, (lines, chars));
}

